// Hero demo: "one human video -> thousands of robot demonstrations". Replays IsaacSim episodes generated by the
// pipeline (xArm7, mug -> coffee machine; hero/episodes.json + episodes.bin, all in the robot-base frame) and lets the
// visitor switch between R2R2R-style data (the one demonstrated mug and machine, randomized poses) and R2S2R data
// (digital cousins too), in one environment or nine parallel ones. The carry phase of every episode follows the mug
// trajectory tracked from the human video, shown in the inset in sync.
import { THREE, createViewer, onTheme, ease, mat4, loadingOverlay, reducedMotion } from '../core/viewer.js';
import { loadXArm } from '../core/robot.js';
import { getObject, objectPath, fetchJSON, fetchBin, url, robustMinZ } from '../core/assets.js';

const SPEED = 2.4;                      // playback speed vs the 10 fps recording
const HOLD = 0.45, SWAP = 1.15;         // seconds held after release, seconds of the swap animation
const GRID = 3, SPACING = 1.08;         // parallel environments
const PHASE_LABEL = ['Reach', 'Reach', 'Approach', 'Grasp', 'Carry · replays the human trajectory', 'Release'];
const MODES = {
  r2r2r: { name: 'R2R2R', long: 'One object pair', col: '--r2r2r', method: 1 },
  ours: { name: 'R2S2R', long: 'Digital cousins', col: '--ours', method: 2 },
};
const css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();
const rnd = n => Math.floor(Math.random() * n);

// ---------------------------------------------------------------- episode data
function decode(meta, buf) {
  const S = meta.scales, st = meta.stride;
  return meta.episodes.map((e, k) => {
    const d = new Int16Array(buf, e.off, e.n * st);
    return Object.assign(e, {
      k, d, st, S,
      Tcm: mat4(e.T_cm),
      pair: e.mug + '+' + e.cm,
      onePair: e.mug === 'demo_mug' && e.cm === 'demo_cm',
    });
  });
}
const _qa = new THREE.Quaternion(), _qb = new THREE.Quaternion();
function sample(ep, f, out) {
  const n = ep.n, st = ep.st, S = ep.S, d = ep.d;
  f = Math.max(0, Math.min(n - 1, f));
  const i0 = Math.floor(f), i1 = Math.min(n - 1, i0 + 1), a = f - i0, o0 = i0 * st, o1 = i1 * st;
  for (let j = 0; j < 7; j++) out.q[j] = ((1 - a) * d[o0 + j] + a * d[o1 + j]) / S.q;
  out.g = ((1 - a) * d[o0 + 7] + a * d[o1 + 7]) / S.g;
  out.p.set(((1 - a) * d[o0 + 8] + a * d[o1 + 8]) / S.p, ((1 - a) * d[o0 + 9] + a * d[o1 + 9]) / S.p,
            ((1 - a) * d[o0 + 10] + a * d[o1 + 10]) / S.p);
  _qa.set(d[o0 + 11], d[o0 + 12], d[o0 + 13], d[o0 + 14]).normalize();
  _qb.set(d[o1 + 11], d[o1 + 12], d[o1 + 13], d[o1 + 14]).normalize();
  out.r.slerpQuaternions(_qa, _qb, a);
  const c = d[(a < 0.5 ? o0 : o1) + 15];
  out.tf = c & 255; out.ph = c >> 8;
  return out;
}
const newSample = () => ({ q: new Float64Array(7), g: 0, p: new THREE.Vector3(), r: new THREE.Quaternion(), tf: 0, ph: 0 });

// ---------------------------------------------------------------- scene pieces
function woodTexture(dark) {
  const c = document.createElement('canvas'); c.width = c.height = 512;
  const g = c.getContext('2d');
  g.fillStyle = dark ? '#a8977f' : '#e9dcc8'; g.fillRect(0, 0, 512, 512);
  for (let i = 0; i < 260; i++) {                       // long soft grain streaks
    const y = Math.random() * 512, h = 0.6 + Math.random() * 2.4;
    g.fillStyle = `rgba(${Math.random() < 0.5 ? '125,95,62' : '255,250,240'},${0.025 + Math.random() * 0.05})`;
    g.fillRect(0, y, 512, h);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace; t.wrapS = t.wrapT = THREE.RepeatWrapping; t.anisotropy = 4;
  return t;
}

function makeRing() {                                    // expanding glow ring played when a new object appears
  const m = new THREE.Mesh(new THREE.RingGeometry(0.8, 1, 48),
    new THREE.MeshBasicMaterial({ color: 0x2f92ff, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide }));
  m.visible = false; m.renderOrder = 3;
  return m;
}

class Trail {                                            // the carried mug path as a glowing tube, revealed as it plays
  constructor(points, color) {
    const curve = new THREE.CatmullRomCurve3(points);
    this.segs = Math.max(8, points.length * 2); this.radial = 6;
    this.mesh = new THREE.Mesh(new THREE.TubeGeometry(curve, this.segs, 0.0024, this.radial, false),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, depthWrite: false }));
    this.mesh.renderOrder = 2;
    this.reveal(0);
  }
  reveal(u) { this.mesh.geometry.setDrawRange(0, Math.floor(Math.max(0, Math.min(1, u)) * this.segs) * this.radial * 6); }
  dispose() { this.mesh.geometry.dispose(); this.mesh.material.dispose(); this.mesh.removeFromParent(); }
}

// ---------------------------------------------------------------- one environment
// An object slot (mug or machine): the shown node, plus an incoming node while a swap brings in a different asset.
class Slot {
  constructor(parent) { this.parent = parent; this.cur = null; this.inc = null; }
  node(mesh, scale) {
    const n = new THREE.Group(); const m = mesh.clone(true); m.scale.setScalar(scale); n.add(m);
    n.userData.mesh = m; n.userData.scale = scale; this.parent.add(n); return n;
  }
}

class Env {
  constructor(app, offset) {
    this.app = app;
    this.group = new THREE.Group(); this.group.position.copy(offset);
    this.table = new THREE.Mesh(app.tableGeo, app.tableMat); this.table.receiveShadow = true;
    this.group.add(this.table);
    this.mug = new Slot(this.group); this.cm = new Slot(this.group);
    this.ringA = makeRing(); this.ringB = makeRing(); this.group.add(this.ringA, this.ringB);
    this.trails = []; this.trail = null; this.s = newSample(); this.s2 = newSample();
    this.state = 'idle'; this.t = 0; this.timer = 0; this.ep = null; this.swap = null;
    this.lastQ = new Float64Array(7); this.lastG = 0;
  }
  async init(robotPromise) { this.robot = await robotPromise; this.group.add(this.robot.root); }
  async prepare(ep) {                                    // load (or reuse) the episode's object meshes
    const [mug, cm] = await Promise.all([this.app.object(ep.mug), this.app.object(ep.cm)]);
    return { ep, mug, cm };
  }
  // A level table at the machine's base (its robust bottom: scanned meshes have stray vertices below the real base).
  // In the generated data the mug's start height and the machine's base disagree by up to ~1.5 cm, so the mug is shown
  // resting on the table and that offset fades out during the carry, while the mug is in the air: the place pose on
  // the tray is the generated one.
  placeTable(ep) {
    const top = new THREE.Vector3(0, 0, this.app.bottom(ep.cm) * ep.cm_scale).applyMatrix4(ep.Tcm).z;
    this.table.quaternion.identity();
    this.table.position.set(0.27, 0.17, top - 0.013);
    const s0 = sample(ep, 0, newSample()), up = new THREE.Vector3(0, 0, 1).applyQuaternion(s0.r);
    const mugBottom = s0.p.z + up.z * this.app.bottom(ep.mug) * ep.mug_scale;
    this.lift0 = Math.max(-0.03, Math.min(0.03, top - mugBottom));
  }
  liftAt(t) {                                            // the start-height offset, faded out over the first 60 % of the carry
    const [e0, e1] = this.execRange, u = (t - e0) / Math.max(1, 0.6 * (e1 - e0));
    return this.lift0 * (1 - ease(u));
  }
  start(prep, { instant = false } = {}) {
    const old = this.ep, ep = prep.ep;
    this.ep = ep; this.execRange = execRange(ep);
    this.placeTable(ep);
    const pts = [], tmp = newSample();                   // carried path = the EXEC frames
    for (let f = this.execRange[0]; f <= this.execRange[1]; f++) { const p = sample(ep, f, tmp).p.clone(); p.z += this.liftAt(f); pts.push(p); }
    this.trail = new Trail(pts, this.app.trailColor());
    this.group.add(this.trail.mesh); this.trails.push(this.trail);
    while (this.trails.length > (this.app.grid ? 6 : 26)) this.trails.shift().dispose();
    sample(ep, 0, this.s); this.s.p.z += this.lift0;
    const cp = new THREE.Vector3().setFromMatrixPosition(ep.Tcm), cq = new THREE.Quaternion().setFromRotationMatrix(ep.Tcm);
    if (instant || !old) {
      for (const sl of [this.mug, this.cm]) { sl.cur && sl.cur.removeFromParent(); sl.inc && sl.inc.removeFromParent(); sl.inc = null; }
      this.mug.cur = this.mug.node(prep.mug, ep.mug_scale); this.mug.cur.position.copy(this.s.p); this.mug.cur.quaternion.copy(this.s.r);
      this.cm.cur = this.cm.node(prep.cm, ep.cm_scale); this.cm.cur.position.copy(cp); this.cm.cur.quaternion.copy(cq);
      this.swap = null; this.state = 'play'; this.t = 0; this.app.onEpisodeStart(this); return;
    }
    const S = this.swap = { u: 0, sameMug: old.mug === ep.mug, sameCm: old.cm === ep.cm,
      mug0: { p: this.mug.cur.position.clone(), r: this.mug.cur.quaternion.clone() }, mug1: { p: this.s.p.clone(), r: this.s.r.clone() },
      cm0: { p: this.cm.cur.position.clone(), r: this.cm.cur.quaternion.clone() }, cm1: { p: cp, r: cq } };
    if (!S.sameMug) { this.mug.inc = this.mug.node(prep.mug, ep.mug_scale); this.mug.inc.position.copy(S.mug1.p); this.mug.inc.quaternion.copy(S.mug1.r); this.mug.inc.visible = false; }
    if (!S.sameCm) { this.cm.inc = this.cm.node(prep.cm, ep.cm_scale); this.cm.inc.position.copy(cp); this.cm.inc.quaternion.copy(cq); this.cm.inc.visible = false; }
    this.state = 'swap'; this.t = 0;
  }
  finishSwap() {
    for (const sl of [this.mug, this.cm]) if (sl.inc) {
      sl.cur.removeFromParent(); sl.cur = sl.inc; sl.inc = null;
      sl.cur.visible = true; sl.cur.userData.mesh.scale.setScalar(sl.cur.userData.scale);
    }
    this.ringA.visible = this.ringB.visible = false;
    this.swap = null; this.state = 'play'; this.t = 0;
    this.app.onEpisodeStart(this);
  }
  pose(s) {
    this.robot.setQ(s.q); this.robot.setGrip(Math.max(0, s.g));
    this.mug.cur.position.copy(s.p); this.mug.cur.position.z += this.liftAt(this.t); this.mug.cur.quaternion.copy(s.r);
  }
  // a slot's swap: the same asset glides (with a hop) to its new pose; a different one shrinks out and the new one pops in
  animSlot(sl, same, a, b, u, ring, ringR, hop) {
    const e = ease(u);
    if (same) {
      sl.cur.position.lerpVectors(a.p, b.p, e); sl.cur.position.z += Math.sin(Math.PI * e) * hop;
      sl.cur.quaternion.slerpQuaternions(a.r, b.r, e);
      return;
    }
    const out = ease(Math.min(1, u / 0.42)), inn = Math.max(0, (u - 0.36) / 0.64);
    sl.cur.userData.mesh.scale.setScalar(sl.cur.userData.scale * Math.max(0.001, 1 - out));
    sl.cur.visible = out < 1;
    sl.inc.visible = inn > 0;
    sl.inc.userData.mesh.scale.setScalar(sl.inc.userData.scale * Math.max(0.001, backOut(inn)));
    const rp = b.p.clone(); rp.z = this.table.position.z + 0.014;
    this.pulse(ring, rp, inn, ringR);
  }
  update(dt) {
    if (!this.ep) return;
    const ep = this.ep;
    if (this.state === 'swap') {
      const S = this.swap; S.u = Math.min(1, S.u + dt / SWAP); const u = S.u, e = ease(u);
      for (let j = 0; j < 7; j++) this.s2.q[j] = this.lastQ[j] + (this.s.q[j] - this.lastQ[j]) * e;
      this.robot.setQ(this.s2.q); this.robot.setGrip(this.lastG * (1 - Math.min(1, u * 3)));
      this.animSlot(this.mug, S.sameMug, S.mug0, S.mug1, u, this.ringA, 0.11, 0.09);
      this.animSlot(this.cm, S.sameCm, S.cm0, S.cm1, u, this.ringB, 0.2, 0.0);
      if (u >= 1) this.finishSwap();
      return;
    }
    if (this.state === 'play') {
      this.t += dt * this.app.fps * SPEED * this.app.speed;
      sample(ep, this.t, this.s); this.pose(this.s);
      const fr = this.execRange;
      this.trail.reveal(this.s.ph < 4 ? 0 : (this.t - fr[0]) / Math.max(1, fr[1] - fr[0]));
      if (this.t >= ep.n - 1) { this.state = 'hold'; this.timer = 0; this.app.onEpisodeDone(this); }
      return;
    }
    if (this.state === 'hold') { this.timer += dt; if (this.timer > HOLD) this.next(); }
  }
  pulse(ring, p, u, r) {
    if (u <= 0 || u >= 1) { ring.visible = false; return; }
    ring.visible = true; ring.position.copy(p);
    ring.scale.setScalar(r * (0.3 + 0.9 * ease(u)));
    ring.material.opacity = 0.8 * (1 - u);
    ring.material.color.copy(this.app.accent);
  }
  async next() {
    if (this.loading || this.state === 'swap' || !this.ep) return;
    this.loading = true;
    for (const tr of this.trails) if (tr !== this.trail) tr.mesh.material.opacity = Math.max(0.1, tr.mesh.material.opacity * 0.72);
    if (this.trail) { this.trail.reveal(Math.max(0, Math.min(1, (this.t - this.execRange[0]) / Math.max(1, this.execRange[1] - this.execRange[0])))); this.trail.mesh.material.opacity = 0.34; }
    sample(this.ep, Math.max(0, Math.min(this.t, this.ep.n - 1)), this.s);
    this.lastQ.set(this.s.q); this.lastG = Math.max(0, this.s.g);
    this.mug.cur.position.copy(this.s.p); this.mug.cur.position.z += this.liftAt(this.t); this.mug.cur.quaternion.copy(this.s.r);
    this.state = 'hold'; this.timer = -1e9;               // frozen while the next episode's meshes load
    const prep = await this.prepare(this.app.pick(this));
    this.loading = false;
    this.start(prep);
  }
}
const backOut = u => { if (u <= 0) return 0; if (u >= 1) return 1; const c = 1.6; return 1 + (c + 1) * Math.pow(u - 1, 3) + c * Math.pow(u - 1, 2); };
function execRange(ep) {
  let a = -1, b = -1; const st = ep.st;
  for (let f = 0; f < ep.n; f++) if ((ep.d[f * st + 15] >> 8) === 4) { if (a < 0) a = f; b = f; }
  return [a, b];
}

// ---------------------------------------------------------------- the app
export async function mount(el) {
  el.innerHTML = '';
  const stage = document.createElement('div'); stage.className = 'demo-stage hero-stage'; el.appendChild(stage);
  const load = loadingOverlay(stage, 'Loading the generated episodes');
  const v = createViewer(stage, { ground: true, groundSize: 12, fov: 30, target: [0.24, 0.16, 0.2], position: [1.62, -1.02, 1.0] });
  v.ground.position.z = -0.05; v.ground.material.opacity = 0.16;
  v.controls.minDistance = 0.5; v.controls.maxDistance = 6.5;

  // UI -------------------------------------------------------------------------------------------------------------
  const hudTL = div('demo-hud tl'), hudBL = div('demo-hud bl'), hudBR = div('demo-hud br');
  const pip = div('hero-pip');
  pip.innerHTML = '<canvas width="256" height="144"></canvas><div class="hero-pip-l"><b>Human video</b><span class="mut f">0 / 100</span></div>';
  stage.append(hudTL, hudBL, hudBR, pip);
  const modePill = div('hud dot'), pairPill = div('hud'), phasePill = div('hud'), epPill = div('hud');
  hudTL.append(modePill, pairPill); hudBL.append(phasePill); hudBR.append(epPill);
  const pctx = pip.querySelector('canvas').getContext('2d'), pf = pip.querySelector('.f');

  const bar = div('demo-bar');
  bar.innerHTML = `
    <div class="seg" role="group" aria-label="Training data">
      <button data-mode="r2r2r" aria-pressed="false"><i style="background:var(--r2r2r)"></i>R2R2R · one pair</button>
      <button data-mode="ours" aria-pressed="true"><i style="background:var(--ours)"></i>R2S2R · cousins</button>
    </div>
    <div class="seg" role="group" aria-label="View">
      <button data-view="1" aria-pressed="true">1 env</button>
      <button data-view="9" aria-pressed="false">9 parallel</button>
    </div>
    <span class="sp"></span>
    <button class="dbtn" data-next><svg viewBox="0 0 24 24"><path d="M5 4l10 8-10 8zM17 4h3v16h-3z"/></svg>Next episode</button>`;
  const stats = div('dstats'); stats.style.setProperty('--n', 3);
  stats.innerHTML = `
    <div class="dstat"><div class="v" data-s="eps">0</div><div class="l">Episodes generated from <b>one</b> human video</div></div>
    <div class="dstat"><div class="v" data-s="pairs">0</div><div class="l">Distinct mug&ndash;machine pairs</div></div>
    <div class="dstat"><div class="v" data-s="real">&ndash;</div><div class="l">Real xArm7 success after training on 2,000 such episodes</div></div>`;
  el.append(bar, stats);
  const $ = s => el.querySelector(s);

  // data -----------------------------------------------------------------------------------------------------------
  let meta, buf;
  try {
    [meta, buf] = await Promise.all([fetchJSON('hero/episodes.json'), fetchBin('hero/episodes.bin')]);
  } catch (e) { load.error('Could not load the episodes.'); throw e; }
  load.set(0.35, 'Loading the robot and the objects');
  const eps = decode(meta, buf);
  const pools = { r2r2r: eps.filter(e => e.onePair), ours: eps };
  const pairsOf = pool => [...new Set(pool.map(e => e.pair))];
  const cousinName = (() => {
    const mugs = [...new Set(eps.map(e => e.mug))].filter(m => m !== 'demo_mug').sort((a, b) => a.localeCompare(b, 'en', { numeric: true }));
    const cms = [...new Set(eps.map(e => e.cm))].filter(m => m !== 'demo_cm').sort((a, b) => a.localeCompare(b, 'en', { numeric: true }));
    return { mug: m => m === 'demo_mug' ? 'demonstrated mug' : 'cousin mug ' + (mugs.indexOf(m) + 1),
             cm: c => c === 'demo_cm' ? 'demonstrated machine' : 'cousin machine ' + (cms.indexOf(c) + 1) };
  })();

  // shared materials ----------------------------------------------------------------------------------------------
  const objCache = new Map(), cmMin = new Map();
  const app = {
    mode: 'ours', grid: false, speed: 1, fps: meta.fps || 10, accent: new THREE.Color(css('--accent') || '#0062d6'),
    tableGeo: new THREE.BoxGeometry(0.98, 0.86, 0.026),
    tableMat: new THREE.MeshStandardMaterial({ roughness: 0.78, metalness: 0 }),
    counts: { r2r2r: { eps: 0, pairs: new Set() }, ours: { eps: 0, pairs: new Set() } },
    object(id) {
      if (!objCache.has(id)) objCache.set(id, getObject(objectPath(id)).then(o => { cmMin.set(id, robustMinZ(o)); return o; }));
      return objCache.get(id);
    },
    bottom: id => cmMin.has(id) ? cmMin.get(id) : -0.07,
    trailColor() { return new THREE.Color(css(MODES[app.mode].col) || '#c51d38'); },
    pick(env) {
      const pool = pools[app.mode];
      if (app.mode === 'ours') {                   // uniform over pairs, then over that pair's episodes
        const prs = pairsOf(pool), pr = prs[rnd(prs.length)];
        const cand = pool.filter(e => e.pair === pr && e !== env.ep);
        return (cand.length ? cand : pool)[rnd(cand.length || pool.length)];
      }
      const cand = pool.filter(e => e !== env.ep);
      return cand[rnd(cand.length)];
    },
    onEpisodeStart(env) { if (env === center) updateHud(); },
    onEpisodeDone(env) {
      const c = app.counts[app.mode]; c.eps += 1; c.pairs.add(env.ep.pair); updateStats(true);
    },
  };
  const envs = [];
  onTheme(dark => {
    app.tableMat.map && app.tableMat.map.dispose();
    app.tableMat.map = woodTexture(dark); app.tableMat.needsUpdate = true;
    app.accent.set(css('--accent') || '#0062d6');
    for (const e of envs) for (const t of e.trails) t.mesh.material.color.set(css(MODES[app.mode].col));
  });

  // environments: index 4 is the centre (the single view) -------------------------------------------------------
  for (let i = 0; i < GRID * GRID; i++) {
    const gx = (i % GRID) - 1, gy = Math.floor(i / GRID) - 1;
    const env = new Env(app, new THREE.Vector3(gx * SPACING, gy * SPACING * 1.02, 0));
    env.group.visible = i === 4;
    envs.push(env); v.scene.add(env.group);
  }
  const center = envs[4];
  await center.init(loadXArm());
  load.set(0.6);
  // first episode: a cousin pair, preloaded
  const first = await center.prepare(app.pick(center));
  load.set(0.95);
  center.start(first, { instant: true });
  center.pose(sample(center.ep, 0, center.s));
  v.fitShadow(new THREE.Vector3(0.28, 0.16, 0), 0.75);
  load.done();
  v.start();

  // demo-video inset ----------------------------------------------------------------------------------------------
  const atlas = new Image(); atlas.decoding = 'async'; atlas.src = url('hero/demo_atlas.webp');
  let lastF = -1;
  function drawPip(f) {
    if (f === lastF || !atlas.complete || !atlas.naturalWidth) return;
    lastF = f; const c = f % 11, r = Math.floor(f / 11);
    pctx.drawImage(atlas, c * 256, r * 144, 256, 144, 0, 0, 256, 144);
    pf.textContent = f + ' / 100';
  }
  atlas.onload = () => { lastF = -1; };

  // camera presets ------------------------------------------------------------------------------------------------
  const camSingle = { p: new THREE.Vector3(1.62, -1.02, 1.0), t: new THREE.Vector3(0.24, 0.16, 0.2) };
  const camGrid = { p: new THREE.Vector3(3.55, -2.75, 3.0), t: new THREE.Vector3(0.3, 0.12, -0.1) };
  function fitFor(preset) {                             // pull back on narrow (portrait) stages
    const [w, h] = v.size, asp = w / h, k = asp < 1.25 ? 1.0 + (1.25 - asp) * 1.2 : 1.0;
    const dir = preset.p.clone().sub(preset.t);
    return { p: preset.t.clone().add(dir.multiplyScalar(k)), t: preset.t.clone() };
  }
  let camTween = null;
  function flyTo(preset, dur = 1.3) {
    const f = fitFor(preset);
    if (reducedMotion()) { v.camera.position.copy(f.p); v.controls.target.copy(f.t); return; }
    camTween = { u: 0, dur, p0: v.camera.position.clone(), t0: v.controls.target.clone(), p1: f.p, t1: f.t };
  }
  { const f = fitFor(camSingle); v.camera.position.copy(f.p); v.controls.target.copy(f.t); }
  v.onResize = () => { if (!camTween) { const f = fitFor(app.grid ? camGrid : camSingle); v.camera.position.copy(f.p); v.controls.target.copy(f.t); } };

  // HUD + stats ---------------------------------------------------------------------------------------------------
  function updateHud() {
    const m = MODES[app.mode];
    modePill.style.setProperty('--c', `var(${m.col})`);
    modePill.innerHTML = `<b>${m.name}</b> <span class="mut">· ${m.long.toLowerCase()}</span>`;
    const ep = center.ep;
    pairPill.innerHTML = app.grid ? `<span class="mut">9 environments, one episode each</span>`
      : `${cap(cousinName.mug(ep.mug))} <span class="mut">&times;</span> ${cousinName.cm(ep.cm)}`;
  }
  const real = (() => {
    const R = window.R2S2R_RESULTS && window.R2S2R_RESULTS.results && window.R2S2R_RESULTS.results.xarm7;
    const row = R && R.find(r => /coffee machine/i.test(r[0]));
    const pc = c => c ? Math.round(100 * c[0] / c[1]) + '<small>%</small>' : '&ndash;';
    return row ? { r2r2r: pc(row[2]), ours: pc(row[3]) } : { r2r2r: '&ndash;', ours: '&ndash;' };
  })();
  function updateStats(bump) {
    const c = app.counts[app.mode];
    const ev = $('[data-s="eps"]'), pv = $('[data-s="pairs"]'), rv = $('[data-s="real"]');
    ev.textContent = c.eps.toLocaleString('en-US');
    pv.textContent = c.pairs.size;
    rv.innerHTML = real[app.mode];
    rv.style.color = `var(${MODES[app.mode].col})`;
    if (bump) { ev.classList.remove('bump'); void ev.offsetWidth; ev.classList.add('bump'); }
  }
  updateHud(); updateStats(false);

  // controls --------------------------------------------------------------------------------------------------------
  function setPressed(sel, attr, val) { el.querySelectorAll(sel).forEach(b => b.setAttribute('aria-pressed', String(b.getAttribute(attr) === val))); }
  el.querySelectorAll('[data-mode]').forEach(b => b.addEventListener('click', () => {
    if (app.mode === b.dataset.mode) return;
    app.mode = b.dataset.mode; setPressed('[data-mode]', 'data-mode', app.mode);
    for (const e of active()) { for (const t of e.trails) t.dispose(); e.trails = []; e.next(); }
    updateHud(); updateStats(false);
  }));
  el.querySelectorAll('[data-view]').forEach(b => b.addEventListener('click', async () => {
    const grid = b.dataset.view === '9'; if (grid === app.grid) return;
    app.grid = grid; setPressed('[data-view]', 'data-view', b.dataset.view);
    v.fitShadow(grid ? new THREE.Vector3(0.26, 0.17, 0) : new THREE.Vector3(0.28, 0.16, 0), grid ? 1.9 : 0.75);
    flyTo(grid ? camGrid : camSingle);
    updateHud();
    for (let i = 0; i < envs.length; i++) {
      if (i === 4) continue;
      const e = envs[i];
      if (!grid) { e.group.visible = false; continue; }
      if (!e.robot) await e.init(loadXArm());
      e.group.visible = true;
      if (!e.ep) { const p = await e.prepare(app.pick(e)); e.start(p, { instant: true }); e.t = -i * 3 - rnd(10); }
      else if (e.state === 'hold') e.next();
    }
  }));
  $('[data-next]').addEventListener('click', () => { for (const e of active()) e.next(); });
  const active = () => envs.filter(e => e.group.visible && e.ep);

  // loop ------------------------------------------------------------------------------------------------------------
  let phaseShown = -1;
  v.add(dt => {
    if (camTween) {
      camTween.u += dt / camTween.dur; const e = ease(camTween.u);
      v.camera.position.lerpVectors(camTween.p0, camTween.p1, e); v.controls.target.lerpVectors(camTween.t0, camTween.t1, e);
      if (camTween.u >= 1) camTween = null;
    }
    for (const e of envs) if (e.group.visible) {
      if (e.state === 'play' && e.t < 0) { e.t += dt * app.fps * SPEED; sample(e.ep, 0, e.s); e.pose(e.s); continue; }   // staggered start
      e.update(dt);
    }
    const s = center.s;
    drawPip(center.state === 'play' ? s.tf : (center.state === 'swap' ? 0 : 100));
    const ph = center.state === 'play' ? s.ph : (center.state === 'swap' ? -2 : -1);
    if (ph !== phaseShown) {
      phaseShown = ph;
      phasePill.innerHTML = ph >= 0 ? `<b>${PHASE_LABEL[ph].split(' · ')[0]}</b>${PHASE_LABEL[ph].includes(' · ') ? ' <span class="mut">· ' + PHASE_LABEL[ph].split(' · ')[1] + '</span>' : ''}`
        : (ph === -2 ? `<b>New episode</b> <span class="mut">· ${app.mode === 'ours' ? 'new objects and poses' : 'same objects, new poses'}</span>` : '<b>Done</b>');
      pip.classList.toggle('live', ph === 4);
    }
    epPill.innerHTML = `<span class="mut">episode</span> <b>${(app.counts[app.mode].eps + 1).toLocaleString('en-US')}</b>`;
  });
}

function div(cls) { const d = document.createElement('div'); d.className = cls; return d; }
function cap(s) { return s.charAt(0).toUpperCase() + s.slice(1); }
